function validate([word1, word2]) {
  for (const [name, word] of [['word1', word1], ['word2', word2]]) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 3000) return `${name} needs 1 to 3000 characters.`;
    if (!/^[a-z]+$/.test(word)) return `${name} may contain only lowercase English letters.`;
  }
  return null;
}

