function largestMerge(word1, word2) {
  let i = 0;
  let j = 0;
  const merge = [];
  while (i < word1.length || j < word2.length) {
    if (word1.slice(i) > word2.slice(j)) {
      merge.push(word1[i]);
      i++;
    } else {
      merge.push(word2[j]);
      j++;
    }
  }
  return merge.join('');
}

