function largestMerge(word1, word2) {
  // Try both choices at every step; memoise the best finish for each pair of positions.
  const memo = new Map();
  const best = (a, b) => {
    if (a === word1.length) return word2.slice(b);
    if (b === word2.length) return word1.slice(a);
    const key = a * 10000 + b;
    if (memo.has(key)) return memo.get(key);
    const takeFirst = word1[a] + best(a + 1, b);
    const takeSecond = word2[b] + best(a, b + 1);
    const result = takeFirst > takeSecond ? takeFirst : takeSecond;
    memo.set(key, result);
    return result;
  };
  return best(0, 0);
}

