function generate(rand, size) {
  const large = size === 'large';
  // Few letters make long ties, where the choice depends on characters far ahead.
  const letters = large
    ? ['ab', 'abc', 'abcdefghijklmnopqrstuvwxyz', 'zy'][Math.floor(rand() * 4)]
    : ['ab', 'abc', 'abcz'][Math.floor(rand() * 3)];
  const skew = rand() < 0.5;
  const word = () => {
    const length = large ? 2000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 7);
    let text = '';
    for (let k = 0; k < length; k++) {
      // A skewed word is mostly its first letter, with rare larger ones.
      const index = skew && rand() < 0.85 ? 0 : Math.floor(rand() * letters.length);
      text += letters[index];
    }
    return text;
  };
  return [word(), word()];
}
